        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
i1=G['Demo pair 1 input']; o1=G['Demo pair 1 output']
i2=G['Demo pair 2 input']; o2=G['Demo pair 2 output']
ti=G['Test input']
def get_comps(inp):
    H,W=len(inp),len(inp[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        for q in range(W):
            c=inp[r][q]
            if c==5 or seen[r][q]: continue
            d=deque([(r,q)]); seen[r][q]=True; cells=[]
            while d:
                rr,qq=d.popleft(); cells.append((rr,qq))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nq=rr+dr,qq+dc
                    if 0<=nr<H and 0<=nq<W and not seen[nr][nq] and inp[nr][nq]==c:
                        seen[nr][nq]=True; d.append((nr,nq))
            rs=[p[0] for p in cells]; qs=[p[1] for p in cells]
            res.append({'c':c,'sz':len(cells),'r0':min(rs),'r1':max(rs),'c0':min(qs),'c1':max(qs)})
    return res
def f(inp):
    O_h,O_w=len(inp)//3,len(inp[0])//3
    res=[[0]*O_w for _ in range(O_h)]
    bycell={}
    for cc in get_comps(inp):
        if cc['c']==0: continue
        for br in range(cc['r0']//3,cc['r1']//3+1):
            for bc in range(cc['c0']//3,cc['c1']//3+1):
                bycell.setdefault((br,bc),[]).append((cc['sz'],cc['c']))
    for (br,bc),items in bycell.items():
        res[br][bc]=max(items,key=lambda x:x[0])[1]
    return res
print('demo1:', f(i1)==o1)
print('demo2:', f(i2)==o2)
